+// URL validation utilities to prevent SSRF (CVE-2025-57822)
+
+const BLOCKED_HOSTS = [
+  'localhost',
+  '127.0.0.1',
+  '0.0.0.0',
+  '::1',
+  '[::1]',
+]
+
+const BLOCKED_PROTOCOLS = ['file:', 'ftp:', 'gopher:', 'data:', 'javascript:', 'vbscript:']
+
+export function isInternalHost(hostname: string): boolean {
+  // Check for localhost variants
+  if (BLOCKED_HOSTS.includes(hostname.toLowerCase())) {
+    return true
+  }
+  
+  // Check for private IP ranges (10.x.x.x, 172.16-31.x.x, 192.168.x.x)
+  if (/^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)/.test(hostname)) {
+    return true
+  }
+  
+  // Check for IPv6 loopback
+  if (hostname === '[::1]' || hostname === '::1') {
+    return true
+  }
+  
+  return false
+}
+
+export function isValidProtocol(protocol: string): boolean {
+  return protocol === 'http:' || protocol === 'https:'
+}

