+import Model from '../models/Model';
+
+/**
+ * Validates that requested fields exist in the model schema
+ * @param model The table/model to validate against
+ * @param fields Comma-separated string of field names
+ * @returns Validation result object
+ */
+export async function validateFields(model: Model, fields: string): Promise<{ valid: boolean; error?: string }> {
+  if (!fields || typeof fields !== 'string') {
+    return { valid: true };
+  }
+  
+  const columns = await model.getColumns();
+  const validColumnNames = new Set(columns.map(col => col.title || col.column_name));
+  const requestedFields = fields.split(',').map(f => f.trim()).filter(f => f);
+  
+  for (const field of requestedFields) {
+    if (!validColumnNames.has(field)) {
+      return { valid: false, error: `Invalid field: ${field}` };
+    }
+  }
+  
+  return { valid: true };
+}

